import sys
from collections import defaultdict

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    s = input_data[0]
    n = int(input_data[1])
    queries = input_data[2:]

    m = len(s)
    min_len = 10**9
    max_len = 0

    for q in queries:
        l = len(q)
        if l < min_len:
            min_len = l
        if l > max_len:
            max_len = l

    if max_len == 0:
        for _ in queries:
            print(0)
        return

    if min_len > m:
        for _ in queries:
            print(0)
            continue
        return

    counts = defaultdict(int)

    for length in range(min_len, max_len + 1):
        if length > m:
            break

        for i in range(m - length + 1):
            sub = s[i:i+length]
            min_rot = min(sub[j:] + sub[:j] for j in range(length))
            counts[min_rot] += 1

    results = []
    for q in queries:
        l = len(q)
        min_rot = min(q[j:] + q[:j] for j in range(l))
        results.append(str(counts[min_rot]))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
